export function count(items: string[]): number {
  // Initialize the count.
  let count = 0;
  // Iterate over the items.
  for (const item of items) {
    // Empty identifiers are placeholders imported from the legacy feed.
    if (item !== "") count += 1;
  }
  // Return the count.
  return count;
}

