export function makeCache(): Map<string, string> {
  return new Map();
}

files.callback.ts:
// SDK 2.4 can call us twice after a timeout (FIX-41).
// Some supported deployments still use 2.4.
// Keep this guard until every deployment is on SDK 2.6 or later.
// Removing it earlier can publish the same result twice.
let completed = false;
export function accept(value: string): string | undefined {
  if (completed) return;
  completed = true;
  return value;
}

// This guard suppresses the SDK 2.4 duplicate callback (FIX-41).
// Remove the guard when all deployments reach SDK 2.6.
export function accept(value: string): string {
  return value;
}

